import { answerQuestion } from './assistant.js';
import { translator, label } from './i18n.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let language=localStorage.getItem('p2p-language')==='ar'?'ar':'en';
let actorId=localStorage.getItem('p2p-actor')||'mgr-airport';
let state=null,view=location.hash.slice(1)||'overview',online=true,busy=false,openId=null,lastFocus=null,checked=false,editingId=null;
let search='',statusFilter='all',typeFilter='all',queueScope='all';
let insightFilters={type:'all',team:'all',from:'',to:''},chat=[],localForecasts=[],auditRows=[],form={};
const t=k=>translator(language)(k), human=v=>label(v,language);
const actor=()=>state?.actors.find(a=>a.id===actorId)||ACTORS.find(a=>a.id===actorId)||ACTORS[0];
const number=n=>n===null||n===undefined?'—':Number(n).toLocaleString(language==='ar'?'ar-AE':'en-GB',{maximumFractionDigits:1});
const date=s=>s?new Date(s).toLocaleString(language==='ar'?'ar-AE':'en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const today=()=>String(state?.asOf||new Date().toISOString()).slice(0,10);
function resetForm(type='transfer'){form={type,department:actor().role==='manager'?actor().department:'Airport Operations',employeeId:'',sourcePositionId:'',targetPositionId:'',effectiveDate:'',justification:'',dependencyRequired:false,dependencyId:'',positionTitle:'',grade:'',endServiceAction:'retain-vacant'};}
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',plus:'M12 5v14 M5 12h14',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',chart:'M4 20V10 M10 20V4 M16 20v-7 M22 20H2',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z M8 12l3 3 5-6',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'m9 5 7 7-7 7',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',alert:'M12 8v5 M12 17h.01 M10 3 1 20h22L14 3z',transfer:'M3 7h17l-4-4 M21 17H4l4 4',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2 M16 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0',file:'M14 2H4v20h16V8z M14 2v6h6 M8 13h8 M8 17h5',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',close:'m6 6 12 12 M6 18 18 6',menu:'M3 6h18 M3 12h18 M3 18h18',link:'M10 13a5 5 0 0 0 7 .5l4-4a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.5l-4 4a5 5 0 0 0 7 7l2-2',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',reset:'M3 11a9 9 0 1 1 2 7 M3 4v7h7',building:'M4 22V3h16v19 M8 7h2 M14 7h2 M8 12h2 M14 12h2 M10 22v-5h4v5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',chat:'M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0 M7 10h10 M7 14h6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',database:'M21 5c0 2-4 4-9 4S3 7 3 5s4-4 9-4 9 2 9 4 M3 5v14c0 2 4 4 9 4s9-2 9-4V5 M3 12c0 2 4 4 9 4s9-2 9-4'};
const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const typeIcon=type=>({transfer:'transfer',create:'building','end-service':'user',delete:'trash'}[type]||'file');
function btn(action,text,ico='plus',kind='primary',extra=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${icon(ico,15)}${esc(text)}</button>`;}
const badge=(text,cls)=>`<span class="chip ${esc(cls)}"><span class="dot"></span>${esc(text)}</span>`;
function toast(message){$('#toast').className='toast';$('#toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},5500);}
const visibleRequests=()=>state.requests.filter(r=>actor().role==='manager'?r.submittedBy===actorId:actor().role==='approver'?(r.ownerId===actorId||r.route?.some(s=>s.ownerId===actorId)):true);
const context=()=>({positions:state.positions});
const prediction=r=>predictRequest(r,state.events,state.asOf,context());
const currentWait=r=>{const last=requestHistory(r.id,state).at(-1);return r.status==='completed'?0:Math.max(0,(Date.parse(state.asOf)-Date.parse(last?.timestamp||r.submittedAt))/3600000);};
function nav(next){closeDrawer();view=next;history.replaceState(null,'',`#${next}`);render();window.scrollTo(0,0);}
function heading(kicker,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="btn-group">${actions}</div></div>`;}
async function loadState(initial=false){try{const response=await fetch('/api/state',{cache:'no-store'});if(response.status===401){if(initial)signInScreen();return;}if(!response.ok)throw Error(t('loadError'));const data=await response.json();const changed=!state||state.version!==data.version;state=data.state;state.version=data.version;online=true;if(!state.actors.some(a=>a.id===actorId))actorId='mgr-airport';if(!Object.keys(form).length)resetForm();if(initial||changed){const drawer=openId;render();if(drawer)showRequest(drawer);}else updateSync();}catch(error){online=false;if(initial&&!state)errorScreen(error.message);else updateSync();}}
async function mutate(action){if(busy||!online)return;busy=true;setBusy();try{const response=await fetch('/api/actions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({expectedVersion:state.version,actorId,action})});const data=await response.json();if(response.status===409){state=data.state;state.version=data.version;const id=openId;render();if(id)showRequest(id);throw Error(t('conflict'));}if(!response.ok){if(data.errors&&view==='new'){checked=true;updateValidation(data);}throw Error(data.error||data.message||t('actionDenied'));}state=data.state;state.version=data.version;online=true;closeDrawer();render();toast(action.type==='submit'||action.type==='resubmit'?t('submittedSuccess'):t('updatedSuccess'));return true;}catch(error){toast(error.message);return false;}finally{busy=false;setBusy();}}
function setBusy(){$$('[data-write],#request-form button[type="submit"]').forEach(e=>e.disabled=busy||!online);}
function updateSync(){$$('[data-sync]').forEach(n=>{n.classList.toggle('disconnected',!online);n.innerHTML=`<span class="dot"></span>${esc(online?t('live'):t('offline'))}${state?` · v${state.version}`:''}`;});setBusy();}
function signInScreen(){document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';$('#app').innerHTML=`<main class="auth-screen"><div class="panel auth-card"><div class="brand-mark" style="margin:0 auto 25px">↗</div><div class="eyebrow muted">P2P COMPASS</div><h1>${t('signInTitle')}</h1><p>${t('signInDesc')}</p><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">${t('signIn')}</a><button class="btn secondary" id="auth-language">${language==='en'?'العربية':'English'}</button></div></main>`;$('#auth-language').onclick=()=>{language=language==='en'?'ar':'en';localStorage.setItem('p2p-language',language);signInScreen();};}
function errorScreen(message){$('#app').innerHTML=`<main class="auth-screen"><section class="panel auth-card"><h1>${t('loadError')}</h1><p>${esc(message)}</p><button class="btn primary" id="retry">${t('retry')}</button></section></main>`;$('#retry').onclick=()=>loadState(true);}
function render(){if(!state)return;document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';document.title=`P2P Compass · ${t(view)}`;
 if(!['overview','new','requests','insights','assistant','evidence','data'].includes(view))view='overview';if(view==='new'&&actor().role!=='manager')view='requests';
 const notices=state.notifications.filter(n=>n.actorId===actorId).slice(-5).reverse();
 const views=[['overview','grid'],...(actor().role==='manager'?[['new','plus']]:[]),['requests','list'],['insights','chart'],['assistant','chat'],['data','database'],['evidence','shield']];
 const pages={overview:overview,new:newRequest,requests:tracker,insights:insights,assistant:assistantPage,evidence:evidencePage,data:dataPage};
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" aria-label="${t('workspace')}"><button class="mobile-close" data-action="menu" aria-label="${t('close')}">${icon('close')}</button><div class="brand"><div class="brand-mark">↗</div><div><b>P2P compass</b><small>${t('peopleOps')}</small></div></div><div class="eyebrow">${t('workspace')}</div><nav class="nav">${views.map(([id,i])=>`<button data-nav="${id}" class="${id===view?'active':''}" ${id===view?'aria-current="page"':''}>${icon(i)}${t(id)}</button>`).join('')}</nav><div class="sidebar-footer"><div class="demo-mini"><strong>${icon('shield',13)} ${t('humanDecisions')}</strong>${t('humanNote')}</div><div class="profile"><div class="avatar">${actor().role==='manager'?'LM':actor().role==='approver'?'AP':'HR'}</div><div><span class="small">${t('demoWorkspace')}</span><small>${t('synthetic')}</small></div></div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Menu">${icon('menu')}</button><div class="breadcrumb">${t('peopleOps')} &nbsp; / &nbsp; <b>${t(view)}</b></div><div class="top-actions"><span class="sync-label" data-sync title="${t('syncNote')}"></span><button class="language-toggle" data-action="language" aria-label="${t('language')}">${language==='en'?'العربية':'English'}</button><span class="chip demo">${t('demo')}</span></div></header><div class="actor-bar"><label for="actor-select">${icon('user',14)} ${t('switchActor')}</label><select id="actor-select">${state.actors.map(a=>`<option value="${esc(a.id)}" ${a.id===actorId?'selected':''}>${esc(a.name)}</option>`).join('')}</select><span class="small muted actor-hint">${t('viewScope')}</span><button class="notification-toggle" data-action="notifications" aria-label="${t('viewNotifications')}">${icon('bell',16)}<span>${notices.length}</span></button></div><div class="notification-panel" id="notifications-panel" hidden><h3>${t('notifications')}</h3>${notices.length?notices.map(n=>`<button data-open="${esc(n.requestId)}"><b>${esc(n.requestId)}</b><span>${esc(n.message)}</span><small>${date(n.at)}</small></button>`).join(''):`<p>${t('noNotifications')}</p>`}</div><main class="content" id="main">${pages[view]()}</main></div></div>`;
 bind();updateSync();if(view==='new')updateValidation();}
function scopedState(){return {...state,requests:visibleRequests()};}
function statCards(){const list=visibleRequests(),stats=analyzeProcess(scopedState()).totals;const overdue=list.filter(r=>r.status!=='completed'&&prediction(r).delay.alreadyDelayed).length;const own=list.filter(r=>r.ownerId===actorId&&r.status!=='completed').length;return `<div class="kpis">${[[t('activeRequests'),stats.active,t('awaitingHuman'),'file',''],[t('myActions'),own,t('assignedToYou'),'user',''],[t('delayed'),overdue,t('alreadyDelayed'),'alert','red'],[t('avgTurnaround'),`${number(stats.avgTurnaroundHours)}<small> h</small>`,t('completedCalendar'),'clock','']].map(([title,value,note,i,cls])=>`<div class="kpi"><div class="kpi-top"><span>${title}</span><span class="kpi-icon">${icon(i,15)}</span></div><span class="kpi-number ${cls}">${value}</span><div class="kpi-note">${note}</div></div>`).join('')}</div>`;}
function probabilityBadge(result,kind,r){if(r.status==='completed')return `<span class="muted small">${t('closed')}</span>`;if(kind==='delay'&&result.alreadyDelayed)return badge(t('alreadyDelayed'),'high');if(kind==='return'&&result.alreadyReturned)return badge(t('alreadyReturned'),'returned');return badge(`${result.probability<.01?'<1':result.probability>.99?'>99':number(result.probability*100)}%`,result.level);}
function filterRequests(list){return list.filter(r=>(!search||`${r.id} ${r.title} ${r.employeeId} ${r.owner}`.toLowerCase().includes(search.toLowerCase()))&&(statusFilter==='all'||r.status===statusFilter)&&(typeFilter==='all'||r.type===typeFilter)&&(queueScope==='all'||queueScope==='mine'&&r.submittedBy===actorId||queueScope==='assigned'&&r.ownerId===actorId||queueScope==='active'&&r.status!=='completed'));}
function requestRows(list){return list.length?list.map(r=>{const p=prediction(r);return `<tr data-request="${esc(r.id)}"><td><div class="request-name"><span class="request-icon">${icon(typeIcon(r.type),15)}</span><div><button class="request-title" data-open="${esc(r.id)}">${human(r.type)}</button><div class="request-meta">${esc(r.id)} · ${esc(r.department)}</div></div></div></td><td>${badge(human(r.status),r.status)}</td><td><div class="owner" title="${esc(r.owner)}">${esc(r.owner)}</div><div class="request-meta">${esc(r.currentStep)}</div></td><td>${probabilityBadge(p.delay,'delay',r)}</td><td>${probabilityBadge(p.return,'return',r)}</td><td>${r.status==='completed'?'—':`${number(currentWait(r))} h`}</td><td>${icon('chevron',12)}</td></tr>`;}).join(''):`<tr><td colspan="7"><div class="empty"><strong>${t('noMatches')}</strong>${t('tryFilters')}</div></td></tr>`;}
function table(list){return `<div class="table-wrap"><table><thead><tr>${['request','status','nextOwner','delayRisk','returnRisk','currentWait'].map(k=>`<th>${t(k)}</th>`).join('')}<th></th></tr></thead><tbody id="request-rows">${requestRows(list)}</tbody></table></div>`;}
function overview(){const s=analyzeProcess(scopedState());const list=visibleRequests().filter(r=>r.status!=='completed').sort((a,b)=>(b.ownerId===actorId)-(a.ownerId===actorId)||prediction(b).delay.probability-prediction(a).delay.probability).slice(0,6);const max=Math.max(...s.bottlenecks.map(b=>b.totalHours),1);return heading(t('overviewKicker'),t('overviewTitle'),t('overviewDesc'),btn('export-predictions',t('exportPredictions'),'download','secondary')+(actor().role==='manager'?btn('new',t('newRequest')):''))+statCards()+`<div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>${t('attentionTitle')}</h2><p>${t('attentionDesc')}</p></div><button class="btn ghost" data-nav="requests">${t('viewAll')} ${icon('arrow',14)}</button></div>${table(list)}<div class="table-footer"><span>${t('showing')} ${list.length} ${t('requestsLabel')}</span><span>${t('businessCalendar')}</span></div></section><div class="side-stack"><section class="panel panel-pad"><div class="eyebrow muted" style="margin-bottom:9px">${t('processPulse')}</div><h2>${t('whereTime')}</h2><p class="small muted" style="font-size:10px;margin-top:7px">${t('cumulative')}</p><div class="flow-list">${s.bottlenecks.slice(0,4).map((b,i)=>`<div class="flow-row"><span class="flow-node">${i+1}</span><div><div class="flow-label">${esc(b.step)}</div><div class="flow-sub">${b.requests} ${t('requestsLabel')} · ${number(b.openHours)} h ${t('openWait')}</div><div class="thin-bar"><i style="width:${Math.max(3,b.totalHours/max*100)}%"></i></div></div><span class="flow-value">${number(b.totalHours)} h</span></div>`).join('')}</div><div class="flow-foot">${t('waitNote')}</div></section><section class="panel spotlight"><div class="eyebrow">${t('opportunities')}</div><h2>${t('spotlightTitle')}</h2><p>${t('spotlightDesc')}</p><button class="btn ghost" data-nav="insights">${t('exploreInsights')} ${icon('arrow',14)}</button></section></div></div><div class="bottom-strip">${icon('shield',20)}<div><strong>${t('transparent')}</strong> ${t('transparentDesc')}</div><button data-nav="evidence">${t('howWorks')} ${icon('arrow',13)}</button></div>`;}
function tracker(){const list=filterRequests(visibleRequests());return heading(t('trackerKicker'),actor().role==='manager'?t('myRequests'):t('reviewQueue'),t('trackerDesc'),btn('export-predictions',t('exportPredictions'),'download','secondary')+(actor().role==='manager'?btn('new',t('newRequest')):''))+`<section class="panel"><div class="panel-head"><div><h2>${t('trackerTitle')} <span class="muted small">${visibleRequests().length}</span></h2><p>${t('viewScope')}</p></div><span class="chip demo">${t('synthetic')}</span></div><div class="filters"><select id="status-filter" aria-label="${t('status')}"><option value="all">${t('allStatuses')}</option>${['pending','blocked','returned','completed'].map(s=>`<option value="${s}" ${statusFilter===s?'selected':''}>${human(s)}</option>`).join('')}</select><select id="type-filter" aria-label="${t('type')}"><option value="all">${t('allTypes')}</option>${Object.keys(WORKFLOWS).map(type=>`<option value="${type}" ${typeFilter===type?'selected':''}>${human(type)}</option>`).join('')}</select><select id="queue-filter" aria-label="${t('scope')}">${[['all','all'],['assigned','assigned'],['mine','submitted'],['active','active']].map(([v,k])=>`<option value="${v}" ${queueScope===v?'selected':''}>${t(k)}</option>`).join('')}</select><input class="search" id="search" aria-label="${t('search')}" placeholder="${t('search')}" value="${esc(search)}"></div>${table(list)}<div class="table-footer"><span id="results-count">${list.length} ${t('matching')}</span><span>${t('live')} · v${state.version}</span></div></section>`;}
function field(name,key,control,hint='',full=false){return `<div class="field ${full?'full':''}"><label for="${name}">${t(key)} *</label>${control}${hint?`<div class="hint">${esc(hint)}</div>`:''}<div class="error" id="err-${name}" aria-live="polite"></div></div>`;}
const input=(name,type='text',placeholder='')=>`<input id="${name}" name="${name}" type="${type}" value="${esc(form[name])}" placeholder="${esc(placeholder)}" aria-describedby="err-${name}" ${type==='date'?`min="${today()}"`:''}>`;
function positionSelect(name){return `<select id="${name}" name="${name}" aria-describedby="err-${name}"><option value="">${t('choosePosition')}</option>${state.positions.filter(p=>p.status!=='deleted').map(p=>`<option value="${esc(p.id)}" ${form[name]===p.id?'selected':''}>${esc(p.id)} · ${esc(p.title)} · ${t(p.status)}</option>`).join('')}</select>`;}
function newRequest(){if(!Object.keys(form).length)resetForm();return heading(t('newKicker'),editingId?t('correctTitle'):t('newTitle'),t('newDesc'),btn('fill-example',t('tryExample'),'spark','secondary'))+`<div class="form-layout"><form id="request-form" class="panel" novalidate><section class="form-section"><div class="section-label"><span class="section-number">1</span><h3>${t('requestType')}</h3></div><div class="type-grid">${Object.keys(WORKFLOWS).map(type=>`<button type="button" class="type-card ${form.type===type?'active':''}" data-type="${type}" aria-pressed="${form.type===type}" ${editingId&&form.type!==type?'disabled':''}>${icon(typeIcon(type),21)}<span>${human(type)}</span></button>`).join('')}</div></section><section class="form-section"><div class="section-label"><span class="section-number">2</span><h3>${t('details')}</h3></div><div class="form-grid">${field('department','department',`<input id="department" name="department" value="${esc(form.department)}" readonly aria-describedby="err-department">`)}${field('effectiveDate','effectiveDate',input('effectiveDate','date'),t('dateHint'))}${['transfer','end-service'].includes(form.type)?field('employeeId','employeeRef',`<input id="employeeId" name="employeeId" value="${esc(form.employeeId)}" placeholder="DEMO-E041" list="employee-options" aria-describedby="err-employeeId"><datalist id="employee-options">${state.employees.filter(e=>e.department===form.department&&e.status!=='ended').map(e=>`<option value="${esc(e.id)}">${esc(e.positionId)}</option>`).join('')}</datalist>`,t('employeeHint')):''}${form.type!=='create'?field('sourcePositionId',form.type==='delete'?'deletePosition':'currentPosition',positionSelect('sourcePositionId')):''}${form.type==='transfer'?field('targetPositionId','targetPosition',positionSelect('targetPositionId'),'',true):''}${form.type==='create'?field('positionTitle','positionTitle',input('positionTitle'))+field('grade','grade',`<select id="grade" name="grade" aria-describedby="err-grade"><option value="">${t('chooseGrade')}</option>${['G5','G6','G7','G8','G9'].map(g=>`<option ${form.grade===g?'selected':''}>${g}</option>`).join('')}</select>`):''}${form.type==='end-service'?field('endServiceAction','endServiceAction',`<select id="endServiceAction" name="endServiceAction"><option value="retain-vacant" ${form.endServiceAction==='retain-vacant'?'selected':''}>${t('retainVacant')}</option><option value="delete-position" ${form.endServiceAction==='delete-position'?'selected':''}>${t('deleteAfter')}</option></select>`,'',true):''}${field('justification','justification',`<textarea id="justification" name="justification" maxlength="5000" placeholder="${t('justificationPlaceholder')}" aria-describedby="err-justification">${esc(form.justification)}</textarea>`,t('justificationHint'),true)}</div></section><section class="form-section"><div class="section-label"><span class="section-number">3</span><h3>${t('dependenciesRouting')}</h3></div><label class="check-label"><input type="checkbox" name="dependencyRequired" id="dependencyRequired" ${form.dependencyRequired?'checked':''}>${t('depends')}</label><div class="field"><label for="dependencyId">${t('upstreamRef')}</label><input name="dependencyId" id="dependencyId" list="dependency-options" value="${esc(form.dependencyId)}" placeholder="P2P-1026" aria-describedby="err-dependencyId"><datalist id="dependency-options">${state.requests.filter(r=>r.id!==editingId).map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('')}</datalist><div class="hint">${t('dependencyHint')}</div><div id="err-dependencyId" class="error"></div></div><div class="route-preview" id="route-preview"></div></section><div class="form-actions"><span class="helper-status">* ${t('required')} · ${RULE_VERSION}</span><div class="btn-group"><button type="button" class="btn secondary" data-action="check">${icon('shield',15)}${t('checkRequest')}</button><button type="submit" class="btn primary" data-write>${icon('arrow',15)}${editingId?t('resubmitReview'):t('submitReview')}</button></div></div></form><div class="side-stack"><section class="panel panel-pad"><div class="eyebrow muted">${t('copilot')}</div><h2 style="margin-top:10px">${t('checkBefore')}</h2><p class="side-note">${t('checksDesc')}</p><div id="validation-panel"></div><div class="side-note">${t('illustrativeRules')}</div></section><section class="panel panel-pad" style="margin-top:20px"><h3>${icon('shield',15)} ${t('synthetic')}</h3><p class="side-note">${t('syntheticWarning')}</p><details style="margin-top:15px"><summary class="small">${t('positionRegister')}</summary><div class="mini-register">${state.positions.map(p=>`<p><b>${esc(p.id)}</b> · ${esc(p.title)} · ${t(p.status)}</p>`).join('')}</div></details></section></div></div>`;}
function readForm(){const node=$('#request-form');if(!node)return;for(const[k,v]of new FormData(node))if(k!=='dependencyRequired')form[k]=v;form.dependencyRequired=$('#dependencyRequired').checked;}
function updateValidation(resultOverride){if(!$('#validation-panel'))return;const result=resultOverride?.checks?resultOverride:validateSubmission(form,state,editingId);const checks=result.checks||[];const passed=checks.filter(c=>c.status==='pass').length;$('#validation-panel').innerHTML=`<div class="validation-summary"><span class="small muted">${t(checked?'checksPassed':'notChecked')}</span><b>${checked?`${passed}<small> / ${checks.length}</small>`:'—'}</b></div><div class="progress-track">${checks.map(c=>`<span class="${checked&&c.status==='pass'?'done':''}"></span>`).join('')}</div><div class="validation-list">${checks.map(c=>`<div class="validation-item"><span class="${checked&&c.status==='fail'?'fail':'check'}">${icon(checked?(c.status==='pass'?'check':'alert'):'clock',14)}</span><div>${esc(c.title)}<small>${esc(c.ruleId)} · ${t(checked?c.status:'notChecked')}</small>${checked&&c.status!=='pass'?`<small>${esc(c.evidence)}</small>`:''}</div></div>`).join('')}</div>${checked?`<div class="notice ${result.valid?'':'warning'}" style="margin-top:20px">${t(result.valid?'readyReview':'issuesResolve')}</div>`:''}`;
 $('#route-preview').innerHTML=`<h3>${t('proposedRoute')}</h3><p class="side-note" style="margin-top:7px">${t('routeSource')}</p><ol>${(result.route||[]).map(s=>`<li><b>${esc(s.step)}</b><span>${esc(s.owner)}</span></li>`).join('')}</ol>`;
 $$('[name]').filter(n=>n.closest('#request-form')).forEach(n=>{const errors=(result.errors||[]).filter(e=>e.field===n.name);n.classList.toggle('invalid',checked&&errors.length>0);n.setAttribute('aria-invalid',String(checked&&errors.length>0));const dest=$(`#err-${n.name}`);if(dest)dest.textContent=checked?errors.map(e=>`${e.message} ${e.fix} ${e.ruleId}`).join(' '):'';});}
async function submitRequest(){readForm();checked=true;const result=validateSubmission(form,state,editingId);updateValidation(result);if(!result.valid){$('#request-form .invalid')?.focus();toast(t('issuesResolve'));return;}const originalId=editingId;const beforeIds=new Set(state.requests.map(r=>r.id));if(await mutate({type:editingId?'resubmit':'submit',...(editingId?{requestId:editingId}:{}),form:{...form}})){const r=originalId?state.requests.find(r=>r.id===originalId):state.requests.find(r=>!beforeIds.has(r.id));editingId=null;checked=false;resetForm();nav('requests');if(r)showRequest(r.id);}}
function nextAction(r){return r.status==='completed'?t('completeAction'):r.status==='returned'?`${t('managerAction')} ${r.lastReturnReason||requestHistory(r.id,state).findLast(e=>e.outcome==='returned')?.returnReason||''}`:r.status==='blocked'?`${t('blockAction')} ${r.blocker?.reason||''}`:t('waitingOwner');}
function fullForm(r){const names=[['type','type'],['employeeId','employeeRef'],['department','department'],['sourcePositionId','currentPosition'],['targetPositionId','targetPosition'],['positionTitle','positionTitle'],['grade','grade'],['effectiveDate','effectiveDate'],['endServiceAction','endServiceAction'],['dependencyId','upstreamRef'],['justification','justification']];return `<dl class="submitted-form">${names.filter(([k])=>r[k]&&(k!=='endServiceAction'||r.type==='end-service')).map(([k,labelKey])=>`<div class="${k==='justification'?'full':''}"><dt>${t(labelKey)}</dt><dd>${k==='type'?human(r[k]):k==='endServiceAction'?t(r[k]==='retain-vacant'?'retainVacant':'deleteAfter'):esc(r[k])}${['sourcePositionId','targetPositionId'].includes(k)?`<small>${esc(state.positions.find(p=>p.id===r[k])?.title||'')}</small>`:''}</dd></div>`).join('')}</dl>`;}
function forecastPanel(r){const p=prediction(r);return `<section class="panel panel-pad detail-panel"><h3>${t('forecast')}</h3><p class="side-note">${t('forecastScope')}</p><div class="forecast-pair">${[['delay',p.delay],['return',p.return]].map(([kind,result])=>`<div><div class="eyebrow muted">${t(kind==='delay'?'delayRisk':'returnRisk')}</div><span class="score">${number(result.probability*100)}<small>%</small></span><span class="forecast-kind">${result.kind==='observed'?(language==='ar'?'نتيجة ملحوظة':'Observed outcome'):t('probability')}</span>${kind==='delay'&&result.alreadyDelayed?badge(t('alreadyDelayed'),'high'):kind==='return'&&result.alreadyReturned?badge(t('alreadyReturned'),'returned'):''}</div>`).join('')}</div>${[['delay',p.delay],['return',p.return]].map(([kind,result])=>`<details class="forecast-reasons" open><summary>${t(kind==='delay'?'delayRisk':'returnRisk')} · ${t('showEvidence')}</summary>${result.reasons.map(e=>`<div class="risk-evidence">${esc(e.text)}<small>${esc(e.evidence)}</small>${e.contribution!==null&&e.contribution!==undefined?`<small>${language==='ar'?'مساهمة في لوغاريتم الأرجحية':'Log-odds contribution'}: ${number(e.contribution)}</small>`:''}</div>`).join('')}</details>`).join('')}<p class="side-note">${(p.dataWarnings||[]).map(w=>`<span class="notice warning" style="display:block;margin-bottom:10px">${esc(w)}</span>`).join('')}${esc(p.modelVersion)} · ${date(p.observationAt)}<br>${t('sourceText')}</p></section>`;}
function reviewPanel(r){const actions=availableActions(r,actorId,state);let html='';if(actions.includes('review'))html+=`<div class="notice info">${t('reviewNote')}</div><div class="btn-group" style="margin:15px 0">${btn('advance',actor().role==='approver'?(language==='ar'?'الموافقة على هذه المرحلة':'Approve this stage'):r.stepIndex===r.route.length-2?(language==='ar'?'تسجيل الإنجاز':'Record completion'):t('advance'),'check','primary',`data-id="${r.id}" data-write`)}</div><details class="action-details"><summary>${t('returnManager')}</summary><label class="field-label" for="return-reason">${t('returnReason')}</label><textarea id="return-reason" class="action-input" placeholder="${t('returnPlaceholder')}" maxlength="1000"></textarea>${btn('return',t('returnManager'),'reset','danger',`data-id="${r.id}" data-write`)}</details>`;
 if(actions.includes('resubmit'))html+=`<div class="notice warning">${esc(r.lastReturnReason||'')}</div>${btn('correct',t('correctTitle'),'file','primary',`data-id="${r.id}"` )}`;
 if(actions.includes('resolve'))html+=`<div class="notice warning">${esc(r.blocker?.reason||'')}</div><label class="field-label" for="resolve-reason">${t('resolutionReason')}</label><textarea id="resolve-reason" class="action-input" maxlength="1000"></textarea>${btn('resolve',t('recordResolution'),'check','primary',`data-id="${r.id}" data-write`)}`;
 if(actions.includes('block'))html+=`<details class="action-details"><summary>${t('blockRequest')}</summary><label class="field-label" for="block-category">${t('blockCategory')}</label><select id="block-category" class="action-input">${['dependency','system','data','routing','other'].map(c=>`<option value="${c}">${t(`category${c[0].toUpperCase()+c.slice(1)}`)}</option>`).join('')}</select><label class="field-label" for="block-reason">${t('blockReason')}</label><textarea id="block-reason" class="action-input" maxlength="1000"></textarea><label class="field-label" for="block-owner">${t('resolutionOwner')}</label><select id="block-owner" class="action-input">${state.actors.filter(a=>a.role!=='process-owner').map(a=>`<option value="${a.id}" ${a.id==='hr-ops'?'selected':''}>${esc(a.name)}</option>`).join('')}</select><label class="field-label" for="block-dependency">${t('upstreamRef')}</label><input id="block-dependency" class="action-input" value="${esc(r.dependencyId)}" placeholder="P2P-1026">${btn('block',t('recordBlock'),'link','secondary',`data-id="${r.id}" data-write`)}</details>`;
 if(actions.includes('assign')){const role=r.route[r.stepIndex]?.role;const owners=state.actors.filter(a=>r.status==='blocked'?a.role!=='process-owner':a.role===role&&(role!=='approver'||a.department===state.actors.find(x=>x.id===r.route[r.stepIndex].ownerId)?.department));html+=`<details class="action-details"><summary>${t('assign')}</summary><p class="side-note">${t('assignNote')}</p><select id="assignment-owner" class="action-input">${owners.map(a=>`<option value="${a.id}" ${a.id===r.ownerId?'selected':''}>${esc(a.name)}</option>`).join('')}</select>${btn('assign',t('recordAssignment'),'user','secondary',`data-id="${r.id}" data-write`)}</details>`;}
 return `<section class="panel panel-pad detail-panel"><h3>${t('humanReview')}</h3>${html||`<p class="side-note">${t('cannotAct')}</p>`}${r.ownerId&&r.ownerId!==actorId&&r.status!=='completed'?`<button class="btn secondary wide" style="margin-top:16px" data-act-as="${esc(r.ownerId)}" data-id="${r.id}">${icon('user',15)}${t('switchActor')}: ${esc(state.actors.find(a=>a.id===r.ownerId)?.name||r.owner)}</button>`:''}</section>`;}
function showRequest(id){const r=visibleRequests().find(r=>r.id===id);if(!r){toast(language==='ar'?'الطلب غير موجود ضمن سجلات هذا الدور.':'This request is outside the selected demo actor’s view.');return;}if(!openId)lastFocus=document.activeElement;openId=id;const history=requestHistory(id,state);const blocker=r.blocker;const checks=r.validationSnapshot?.checks||[];
 $('#overlay').innerHTML=`<div class="modal-backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1"><div class="drawer-header"><div><div class="eyebrow muted">${esc(id)} · ${t('synthetic')}</div><h2 id="detail-title">${human(r.type)}</h2><p class="small muted" style="margin-top:7px">${esc(r.department)}</p></div><button class="close-btn" data-close aria-label="${t('close')}">${icon('close',16)}</button></div><div class="drawer-content"><div class="panel detail-panel"><div class="detail-grid"><div><label>${t('status')}</label>${badge(human(r.status),r.status)}</div><div><label>${t('currentStep')}</label><b>${esc(r.currentStep)}</b></div><div><label>${t('nextOwner')}</label><b>${esc(r.owner)}</b></div><div><label>${t('currentWait')}</label><b>${r.status==='completed'?t('closed'):`${number(currentWait(r))} h`}</b></div><div><label>${t('submittedAt')}</label><b>${date(r.submittedAt)}</b></div><div><label>${t('target')}</label><b>${r.targetHours} ${t('calendarHours')}</b></div></div><div class="notice info" style="margin:0 18px 18px"><strong>${t('nextAction')}</strong><br>${esc(nextAction(r))}</div>${blocker?`<div class="notice warning" style="margin:0 18px 18px"><strong>${t('blockCategory')}: ${esc(blocker.category)}</strong><br>${esc(blocker.reason)}<br>${t('resolutionOwner')}: ${esc(blocker.resolutionOwner)}</div>`:''}${r.dependencyId?`<div class="dependency-card"><b>${t('blockedBy')}</b><button data-open="${esc(r.dependencyId)}">${esc(r.dependencyId)} ${icon('chevron',12)}</button><small>${esc(state.requests.find(x=>x.id===r.dependencyId)?.owner||'')} · ${human(state.requests.find(x=>x.id===r.dependencyId)?.status||'unknown')}</small></div>`:''}</div>${reviewPanel(r)}<section class="panel panel-pad detail-panel"><h3>${t('submittedForm')}</h3>${fullForm(r)}</section><section class="panel panel-pad detail-panel"><h3>${t('validationSnapshot')}</h3><p class="side-note">${t('ruleVersion')}: ${esc(r.validationSnapshot?.ruleVersion||r.workflowVersion)} · ${t('formVersion')} ${r.formRevisions?.length||1}<br>${date(r.validationSnapshot?.at)}<br>${esc(r.validationSnapshot?.provenance||t('savedChecks'))}</p>${checks.map(c=>`<div class="risk-evidence"><b>${esc(c.ruleId)} · ${esc(c.title)}</b> ${badge(t(c.status),c.status==='fail'?'high':c.status==='warning'?'medium':'low')}<small>${esc(c.evidence)}</small></div>`).join('')}</section><section class="panel panel-pad detail-panel"><h3>${t('route')}</h3><ol class="detail-route">${(r.route||[]).map((s,i)=>`<li class="${i===r.stepIndex?'current':''}"><span>${i+1}</span><div><b>${esc(s.step)}</b><small>${esc(s.owner)}</small></div></li>`).join('')}</ol><p class="side-note">${t('routeSource')} · ${esc(r.workflowVersion)}</p></section>${forecastPanel(r)}<section class="panel panel-pad detail-panel"><h3>${t('history')}</h3><p class="side-note">${t('recordedHistory')}</p><div class="timeline">${history.map(e=>`<div class="timeline-event"><div class="timeline-dot"></div><div><h3>${esc(e.step)} <span class="muted">· ${esc(e.outcome.replaceAll('_',' '))}</span></h3><p>${esc(e.actor)} · ${date(e.timestamp)}</p>${e.returnReason||e.reason?`<p class="${e.outcome==='returned'?'return-note':''}">${esc(e.returnReason||e.reason)}</p>`:''}<p class="event-id">${esc(e.id)}</p></div></div>`).join('')}</div><details><summary class="small">${t('formRevisions')} (${r.formRevisions?.length||0})</summary>${(r.formRevisions||[]).map(rev=>`<div class="revision"><b>${t('version')} ${rev.version} · ${date(rev.at)}</b><p>${esc(rev.form?.justification||'')}</p><small>${esc(rev.actorId)} · ${esc(rev.validationSnapshot?.ruleVersion||'')}</small></div>`).join('')}</details></section></div></section></div>`;
 $('#app').inert=true;document.body.style.overflow='hidden';$('.drawer').focus();bindOverlay();setBusy();}
function closeDrawer(){if(!openId)return;openId=null;$('#overlay').innerHTML='';$('#app').inert=false;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function insightControls(){return `<form id="insight-filters" class="panel filter-panel"><div class="field"><label for="insight-type">${t('type')}</label><select id="insight-type" name="type"><option value="all">${t('allTypes')}</option>${Object.keys(WORKFLOWS).map(type=>`<option value="${type}" ${insightFilters.type===type?'selected':''}>${human(type)}</option>`).join('')}</select></div><div class="field"><label for="insight-team">${t('team')}</label><select id="insight-team" name="team"><option value="all">${t('allTeams')}</option>${[...new Set(visibleRequests().map(r=>r.department))].map(team=>`<option ${insightFilters.team===team?'selected':''}>${esc(team)}</option>`).join('')}</select></div><div class="field"><label for="insight-from">${t('from')}</label><input type="date" id="insight-from" name="from" value="${esc(insightFilters.from)}"></div><div class="field"><label for="insight-to">${t('to')}</label><input type="date" id="insight-to" name="to" value="${esc(insightFilters.to)}"></div><button type="submit" class="btn primary">${t('applyFilters')}</button><button type="button" class="btn secondary" data-action="clear-insights">${t('resetFilters')}</button></form>`;}
function insights(){const s=analyzeProcess(scopedState(),insightFilters),max=Math.max(...s.bottlenecks.map(b=>b.totalHours),1);return heading(t('insightsKicker'),t('insightsTitle'),t('insightsDesc'),btn('export-recs',t('exportRecommendations'),'download','secondary'))+`<div class="notice" style="margin-bottom:20px">${icon('shield',15)} ${t('demoFindings')}</div>${insightControls()}<div class="insight-grid"><section class="panel panel-pad"><h2>${t('elapsedStep')}</h2><p class="side-note">${t('elapsedStepDesc')}</p>${s.bottlenecks.map(b=>`<div class="chart-row"><div><div class="chart-name">${esc(b.step)}</div><div class="chart-meta">${b.requests} ${t('requestsLabel')}</div></div><div class="chart-track"><div class="chart-bar" style="width:${b.totalHours/max*100}%"></div></div><div class="chart-value">${number(b.totalHours)} h</div></div>`).join('')||`<p class="empty">${t('noRows')}</p>`}<p class="footer-note">${esc(s.waitBasis)}<br>${t('sourceText')}</p></section><section class="panel panel-pad"><h2>${t('loopsTitle')}</h2><p class="side-note">${t('loopDesc')}</p>${s.loops.map(l=>`<div class="loop-item"><div class="loop-head"><b>${esc(l.reason)}</b><span class="chip returned">${l.count}</span></div><div class="loop-links">${l.requestIds.map(id=>`<button class="link-chip" data-open="${esc(id)}">${esc(id)} ↗</button>`).join('')}</div></div>`).join('')||`<p class="empty">${t('noRows')}</p>`}<div class="divider"></div><h3>${t('exceptions')}</h3>${s.exceptions.map(e=>`<div class="method-row"><span>${esc(e.category)}</span><b>${e.count} ${t('requestsLabel')}</b></div>`).join('')||`<p class="side-note">${t('noRows')}</p>`}</section></div><section class="panel"><div class="panel-head"><div><h2>${t('teamComparison')}</h2><p>${t('teamCompareNote')}</p></div></div><div class="table-wrap"><table><thead><tr>${['team','type','count','median','p90','returnRate','openCases'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${s.teamComparison.map(row=>`<tr><td>${esc(row.team)}</td><td>${human(row.type)}</td><td>${row.count}</td><td>${number(row.medianHours)} h</td><td>${number(row.p90Hours)} h</td><td>${number(row.returnRate)}%</td><td>${row.openCount}</td></tr>`).join('')||`<tr><td colspan="7" class="empty">${t('noRows')}</td></tr>`}</tbody></table></div></section><div class="insight-grid" style="margin-top:22px"><section class="panel panel-pad"><h2>${t('variants')}</h2>${s.variants.map(v=>`<details class="variant-detail"><summary><span>${esc(v.path)}</span><b>${v.count}</b></summary><div class="loop-links">${v.requestIds.map(id=>`<button class="link-chip" data-open="${esc(id)}">${esc(id)}</button>`).join('')}</div></details>`).join('')||`<p class="empty">${t('noRows')}</p>`}<p class="footer-note">${t('partialPaths')}</p></section><section class="panel panel-pad"><h2>${t('trends')}</h2><div class="table-wrap"><table><thead><tr><th>${t('period')}</th><th>${t('count')}</th><th>${t('completed')}</th><th>${t('avgTurnaround')}</th></tr></thead><tbody>${s.trend.map(p=>`<tr><td>${esc(p.period)}</td><td>${p.count}</td><td>${p.completed}</td><td>${number(p.avgHours)} h</td></tr>`).join('')}</tbody></table></div></section></div><div class="section-heading"><div><h2>${t('recommendations')}</h2><p>${t('recDesc')}</p></div><span class="chip demo">${t('scenario')}</span></div><div class="recommendations">${s.recommendations.map((r,i)=>`<article class="panel recommendation"><span class="rec-icon">${icon(['shield','transfer','link'][i%3],19)}</span><div class="eyebrow muted" style="margin-bottom:8px">${esc(r.id)} · ${r.affectedCount} ${t('requestsLabel')}</div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><div class="savings">${number(r.elapsedHoursSaved)} h <small>${t('elapsedOpportunity')}</small></div><div class="rec-meta">${t('range')}: ${number(r.lowHoursSaved)}–${number(r.highHoursSaved)} h · ${t('scenario')}</div><details><summary>${t('showEvidence')}</summary><p>${esc(r.evidence)}</p><p><strong>${t('assumption')}:</strong> ${esc(r.assumption)}</p><p><strong>${t('calculation')}:</strong> ${esc(r.calculation)}</p><p><strong>${t('nextSteps')}:</strong> ${r.steps.map(esc).join(' → ')}</p><p>${esc(r.caveat)}</p><div class="loop-links">${r.requestIds.map(id=>`<button class="link-chip" data-open="${esc(id)}">${esc(id)} ↗</button>`).join('')}</div></details></article>`).join('')||`<p class="empty">${t('noRows')}</p>`}</div><p class="footer-note">${t('labourUnknown')}</p>`;}
function assistantPage(){return heading(t('assistantKicker'),t('assistantTitle'),t('assistantDesc'))+`<section class="panel assistant-panel"><div class="notice info">${t('assistantMethod')}</div><div class="suggestion-list">${['sampleStatus','sampleActions','sampleBlock','sampleBottleneck'].map(k=>`<button data-question="${esc(t(k))}">${icon('chat',14)} ${t(k)}</button>`).join('')}</div><div class="chat-history" aria-live="polite">${chat.map(item=>`<article class="chat-turn"><div class="chat-question">${esc(item.question)}</div><div class="chat-answer">${esc(item.answer)}</div><div class="loop-links">${item.evidence.map(e=>e.requestId?`<button class="link-chip" data-open="${esc(e.requestId)}">${esc(e.label)}${e.eventId?` · ${esc(e.eventId)}`:''}</button>`:`<span class="link-chip">${esc(e.label)}</span>`).join('')}</div></article>`).join('')}</div><form id="assistant-form" class="ask-form"><label class="sr-only" for="question">${t('askPlaceholder')}</label><input id="question" name="question" placeholder="${t('askPlaceholder')}" maxlength="500" required><button class="btn primary" type="submit">${icon('arrow',15)}${t('ask')}</button></form></section>`;}
function evidencePage(){const card=MODEL_CARD;return heading(t('evidence'),t('evidenceTitle'),t('evidenceDesc'))+`<div class="evidence-layout"><section class="panel panel-pad"><h2>${t('coverage')}</h2>${['coverageSubmission','coverageTracking','coveragePrediction','coverageProcess','coverageRecommendations','coverageAssistant','coverageLanguages'].map(k=>`<div class="coverage-row"><span class="check">${icon('check',17)}</span><div><b>${t(k)}</b><small>${t('implemented')}</small></div></div>`).join('')}<p class="side-note">${t('forecastScope')}</p></section><section class="panel panel-pad prose"><h3>${t('limitations')}</h3><p>${t('responsibleText')}</p><p style="margin-top:14px">${t('illustrativeRules')} ${t('businessCalendar')}</p><p style="margin-top:14px">${t('localOnly')}</p><div class="notice warning" style="margin-top:18px">${t('mappingNote')}</div></section><section class="panel panel-pad wide-panel"><h2>${t('modelCard')}</h2><div class="model-meta"><p><b>${card.version}</b><br>${esc(card.method)}</p><p>${t('trainingCases')}: <b>${card.split.trainCases}</b><br>${t('testCases')}: <b>${card.split.testCases}</b></p><p>${t('testPeriod')}:<br>${date(card.split.testFrom)} — ${date(card.split.testTo)}</p></div><div class="notice warning">${t('forecastScope')}</div><div class="table-wrap"><table><thead><tr>${['outcome','count','precision','recall','brier','baselineBrier'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${['delay','return'].map(k=>{const m=card.metrics[k];return `<tr><td>${t(k==='delay'?'delayRisk':'returnRisk')}</td><td>${m.n}</td><td>${number(m.precision*100)}%</td><td>${number(m.recall*100)}%</td><td>${m.brier.toFixed(3)}</td><td>${m.baselineBrier.toFixed(3)}</td></tr>`;}).join('')}</tbody></table></div><p class="side-note">Threshold: ${card.threshold}. ${esc(card.observationPolicy)}</p><details class="method-details"><summary>${t('leakageControls')}</summary><ul>${card.leakageControls.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details><details class="method-details"><summary>${t('limitations')}</summary><ul>${card.limitations.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details><div class="btn-group" style="margin-top:18px">${btn('export-model',t('exportModel'),'download','secondary')}${btn('export-predictions',t('exportPredictions'),'download','secondary')}</div></section><section class="panel panel-pad wide-panel"><div class="section-heading" style="margin-top:0"><div><h2>${t('audit')}</h2><p>${t('auditDesc')}</p></div>${btn('load-audit',t('loadAudit'),'list','secondary')}</div><div id="audit-results">${auditMarkup()}</div><div class="divider"></div><div class="btn-group">${btn('export-events',t('exportEvents'),'download','secondary')}${['hr','process-owner'].includes(actor().role)?btn('reset',t('resetDemo'),'reset','secondary'):''}</div><div id="reset-confirm" hidden><p class="notice warning" style="margin-top:15px">${t('resetWarning')}</p>${btn('confirm-reset',t('confirmReset'),'reset','danger','data-write')}</div></section></div>`;}
function auditMarkup(){return auditRows.length?`<div class="table-wrap"><table><thead><tr><th>${t('version')}</th><th>${t('switchActor')}</th><th>${t('actions')}</th><th>${t('request')}</th><th>${t('history')}</th></tr></thead><tbody>${auditRows.map(row=>`<tr><td>${row.version}</td><td>${esc(row.actorId)}</td><td>${esc(row.action)}</td><td>${esc(row.requestId||'—')}</td><td>${date(row.timestamp)}</td></tr>`).join('')}</tbody></table></div>`:`<p class="side-note">${t('noRows')}</p>`;}
function dataPage(){return heading(t('data'),t('dataTitle'),t('dataDesc'),btn('sample-csv',t('downloadSample'),'download','secondary'))+`<div class="notice info" style="margin-bottom:20px">${t('localOnly')}</div><section class="panel panel-pad"><h2>${t('importRequests')}</h2><p class="side-note">${t('csvSchema')}</p><form id="csv-form" class="csv-form"><div class="field"><label for="csv-requests">${t('importRequests')}</label><input id="csv-requests" type="file" accept=".csv,text/csv" required></div><div class="field"><label for="csv-events">${t('importEvents')}</label><input id="csv-events" type="file" accept=".csv,text/csv"></div><div class="field"><label for="csv-observation">${t('observationTime')}</label><input id="csv-observation" type="datetime-local" step="1" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,19)}" required></div><button type="submit" class="btn primary">${icon('chart',15)}${t('scoreCSV')}</button></form><p class="notice warning">${t('mappingNote')}</p><div id="csv-results">${localForecasts.length?`<p class="side-note">${localForecasts.length} ${t('requestsLabel')} · ${MODEL_CARD.version}</p>${btn('export-local',t('exportLocal'),'download','secondary')}`:''}</div></section>`;}
function ask(question){if(!question.trim())return;const result=answerQuestion(question,state,actorId,language);chat.push({question,...result});if(chat.length>20)chat.shift();render();$('#question')?.focus();}
function bindRequests(root='#app'){$$(`${root} [data-open]`).forEach(n=>n.onclick=e=>{e.stopPropagation();showRequest(n.dataset.open);});$$(`${root} [data-request]`).forEach(n=>n.onclick=()=>showRequest(n.dataset.request));}
function bind(){bindRequests();$$('#app [data-nav]').forEach(n=>n.onclick=()=>{search='';queueScope='all';statusFilter='all';typeFilter='all';nav(n.dataset.nav);});$$('#app [data-action]').forEach(n=>n.onclick=()=>action(n.dataset.action,n.dataset.id));$('#actor-select').onchange=e=>{closeDrawer();actorId=e.target.value;localStorage.setItem('p2p-actor',actorId);chat=[];checked=false;editingId=null;resetForm();queueScope='all';search='';render();};
 if($('#search'))$('#search').oninput=e=>{search=e.target.value;const list=filterRequests(visibleRequests());$('#request-rows').innerHTML=requestRows(list);$('#results-count').textContent=`${list.length} ${t('matching')}`;bindRequests();};
 for(const[id,set]of[['status-filter',v=>statusFilter=v],['type-filter',v=>typeFilter=v],['queue-filter',v=>queueScope=v]])if($(`#${id}`))$(`#${id}`).onchange=e=>{set(e.target.value);render();};
 if($('#request-form')){$('#request-form').onsubmit=e=>{e.preventDefault();submitRequest();};$('#request-form').oninput=()=>{readForm();if(checked)updateValidation();};$('#request-form').onchange=()=>{readForm();updateValidation();};$$('[data-type]').forEach(n=>n.onclick=()=>{const type=n.dataset.type;resetForm(type);checked=false;render();});}
 if($('#insight-filters'))$('#insight-filters').onsubmit=e=>{e.preventDefault();insightFilters=Object.fromEntries(new FormData(e.target));render();};
 $$('[data-question]').forEach(n=>n.onclick=()=>ask(n.dataset.question));if($('#assistant-form'))$('#assistant-form').onsubmit=e=>{e.preventDefault();ask($('#question').value);};
 if($('#csv-form'))$('#csv-form').onsubmit=e=>{e.preventDefault();scoreCSV();};}
function bindOverlay(){bindRequests('#overlay');$$('#overlay [data-action]').forEach(n=>n.onclick=()=>action(n.dataset.action,n.dataset.id));$$('[data-close]').forEach(n=>n.onclick=closeDrawer);$('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeDrawer();};$$('[data-act-as]').forEach(n=>n.onclick=()=>{const id=n.dataset.id;actorId=n.dataset.actAs;localStorage.setItem('p2p-actor',actorId);closeDrawer();nav('requests');showRequest(id);});}
async function action(name,id){switch(name){case'menu':$('.sidebar').classList.toggle('open');break;case'language':readForm();language=language==='en'?'ar':'en';localStorage.setItem('p2p-language',language);chat=[];render();if(openId)showRequest(openId);break;case'notifications':$('#notifications-panel').hidden=!$('#notifications-panel').hidden;break;case'new':editingId=null;checked=false;resetForm();nav('new');break;case'fill-example':{resetForm();const source=state.positions.find(p=>p.department===actor().department&&p.status==='occupied');const employee=state.employees.find(e=>e.positionId===source?.id&&e.status!=='ended');Object.assign(form,{employeeId:employee?.id||'',sourcePositionId:source?.id||'',targetPositionId:source?.id||'',effectiveDate:today(),justification:'Move'});checked=true;render();break;}case'check':readForm();checked=true;updateValidation();if(!validateSubmission(form,state,editingId).valid)$('#request-form .invalid')?.focus();break;case'correct':{const r=state.requests.find(r=>r.id===id);form={...r};editingId=id;checked=true;closeDrawer();nav('new');break;}case'advance':await mutate({type:'review',requestId:id,decision:'advance',reason:'Explicit human confirmation in synthetic demo'});showRequest(id);break;case'return':{const reason=$('#return-reason').value;if(await mutate({type:'review',requestId:id,decision:'return',reason}))showRequest(id);break;}case'block':{const category=$('#block-category').value,reason=$('#block-reason').value,resolutionOwnerId=$('#block-owner').value,dependencyId=$('#block-dependency').value;if(await mutate({type:'block',requestId:id,category,reason,resolutionOwnerId,...(category==='dependency'?{dependencyId}:{})}))showRequest(id);break;}case'resolve':{const reason=$('#resolve-reason').value;if(await mutate({type:'resolve',requestId:id,reason}))showRequest(id);break;}case'assign':{const ownerId=$('#assignment-owner').value;if(await mutate({type:'assign',requestId:id,ownerId}))showRequest(id);break;}case'clear-insights':insightFilters={type:'all',team:'all',from:'',to:''};render();break;case'export-predictions':downloadCSV('p2p-demo-predictions.csv',predictionRows(visibleRequests(),state.events,state.asOf,context()));break;case'export-events':downloadCSV('p2p-demo-events.csv',state.events.filter(e=>visibleRequests().some(r=>r.id===e.requestId)));break;case'export-model':download('p2p-demo-model-report.json',JSON.stringify(getModelReport(),null,2),'application/json');break;case'export-recs':download('p2p-demo-recommendations.json',JSON.stringify({observationAt:state.asOf,scope:t('demoFindings'),recommendations:analyzeProcess(scopedState(),insightFilters).recommendations},null,2),'application/json');break;case'load-audit':{const response=await fetch('/api/audit');const result=await response.json();if(!response.ok){toast(result.error);break;}auditRows=result.entries;$('#audit-results').innerHTML=auditMarkup();break;}case'reset':$('#reset-confirm').hidden=false;break;case'confirm-reset':await mutate({type:'reset'});break;case'sample-csv':downloadCSV('p2p-inflight-sample.csv',visibleRequests().filter(r=>r.status!=='completed').slice(0,10).map(r=>Object.fromEntries(['id','type','department','submittedAt','effectiveDate','employeeId','sourcePositionId','targetPositionId','justification','dependencyId','targetHours'].map(k=>[k,r[k]||'']))));break;case'export-local':downloadCSV('p2p-local-forecasts.csv',localForecasts);break;}}
function csvCell(value){let v=typeof value==='object'?JSON.stringify(value):String(value??'');if(/^[=+\-@\t\r]/.test(v))v=`'${v}`;return `"${v.replaceAll('"','""')}"`;}
function downloadCSV(name,rows){if(!rows.length){toast(t('noRows'));return;}const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))];download(name,[keys,...rows.map(r=>keys.map(k=>r[k]))].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${t('downloaded')}: ${name}`);}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV has an unterminated quoted field.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error('CSV must contain a header and at least one data row.');const headers=rows.shift().map(h=>h.replace(/^\uFEFF/,'').trim());if(new Set(headers).size!==headers.length)throw Error('CSV contains duplicate column names.');return rows.map((r,i)=>{if(r.length!==headers.length)throw Error(`CSV row ${i+2} has a different number of columns.`);return Object.fromEntries(headers.map((h,j)=>[h,r[j].trim()]));});}
async function scoreCSV(){try{const file=$('#csv-requests').files[0],eventFile=$('#csv-events').files[0];if(!file)return;if(file.size>10*1024*1024||eventFile?.size>10*1024*1024)throw Error('Use files smaller than 10 MB.');const asOf=new Date($('#csv-observation').value).toISOString();const rows=parseCSV(await file.text());if(rows.length>10000)throw Error('This browser demo supports up to 10,000 request rows.');const seen=new Set();for(const r of rows){if(!r.id||seen.has(r.id)||!WORKFLOWS[r.type]||!Number.isFinite(Date.parse(r.submittedAt))||!(Number(r.targetHours)>0))throw Error('Each request needs a unique id, supported type, valid submittedAt and positive targetHours.');seen.add(r.id);r.targetHours=Number(r.targetHours);r.dependencyRequired=!!r.dependencyId;}const log=eventFile?parseCSV(await eventFile.text()):[];for(const e of log)if(!e.requestId||!e.id||!e.step||!Number.isFinite(Date.parse(e.timestamp)))throw Error('Each event needs id, requestId, step and a valid timestamp.');localForecasts=predictionRows(rows,log,asOf,context());$('#csv-results').innerHTML=`<p class="side-note">${localForecasts.length} ${t('requestsLabel')} · ${MODEL_CARD.version}</p>${btn('export-local',t('exportLocal'),'download','secondary')}<p class="side-note">${t('forecastScope')}</p>`;$('#csv-results [data-action]').onclick=()=>action('export-local');}catch(error){toast(error.message);}}
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'overview';closeDrawer();render();});
document.addEventListener('keydown',e=>{if(!openId)return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const nodes=$$('.drawer button,.drawer input,.drawer textarea,.drawer select,.drawer summary').filter(n=>!n.disabled&&n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('drawer'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadState();});
$('#app').innerHTML=`<main class="auth-screen"><p>${t('syncing')}</p></main>`;loadState(true);setInterval(()=>{if(!document.hidden&&!busy)loadState();},5000);
